CREATE TABLE IF NOT EXISTS `letter_template_defs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `template_key` varchar(60) COLLATE utf8mb4_unicode_ci NOT NULL,
  `label` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `label_en` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `employee` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'optional',
  `fields` json DEFAULT NULL,
  `body_id` longtext COLLATE utf8mb4_unicode_ci,
  `body_en` longtext COLLATE utf8mb4_unicode_ci,
  `closing_id` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `closing_en` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `page_size` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `page_orientation` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `margin_top` decimal(5,2) DEFAULT NULL,
  `margin_right` decimal(5,2) DEFAULT NULL,
  `margin_bottom` decimal(5,2) DEFAULT NULL,
  `margin_left` decimal(5,2) DEFAULT NULL,
  `is_system` tinyint(1) NOT NULL DEFAULT '0',
  `created_by` bigint unsigned DEFAULT NULL,
  `updated_by` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `letter_template_defs_template_key_unique` (`template_key`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

