INSERT  IGNORE INTO `letter_template_defs` (`id`, `template_key`, `label`, `label_en`, `description`, `employee`, `fields`, `body_id`, `body_en`, `closing_id`, `closing_en`, `page_size`, `page_orientation`, `margin_top`, `margin_right`, `margin_bottom`, `margin_left`, `is_system`, `created_by`, `updated_by`, `created_at`, `updated_at`) VALUES (1,'employment_certificate','Surat Keterangan Kerja','Employment Certificate','States that the employee works at the company: name, employee ID, position, department and join date are filled in automatically.','required','{\"purpose\": {\"type\": \"text\", \"label\": \"Purpose of the letter\", \"required\": true, \"placeholder\": \"e.g. visa application, bank loan\"}}','<p style=\"text-align:center\"><strong><u>SURAT KETERANGAN KERJA</u></strong></p><p style=\"text-align:center\">Nomor: {{letter_number}}</p><p>Yang bertanda tangan di bawah ini:</p><table style=\"margin-left:20pt\"><tbody><tr><td style=\"width:120pt\">Nama</td><td style=\"width:12pt\">:</td><td><strong>{{signer_name}}</strong></td></tr><tr><td style=\"width:120pt\">Jabatan</td><td style=\"width:12pt\">:</td><td><strong>{{signer_title}}</strong></td></tr></tbody></table><p>Dengan ini menerangkan bahwa:</p><p>{{employee_details}}</p><p>adalah benar karyawan {{company}} yang bekerja sejak {{join_date}} sampai dengan tanggal surat ini dibuat.</p><p>Surat keterangan ini dibuat untuk keperluan {{purpose}}.</p><p>Demikian surat keterangan ini dibuat dengan sebenarnya untuk dapat dipergunakan sebagaimana mestinya.</p><p>{{signature_block}}</p>','<p style=\"text-align:center\"><strong><u>EMPLOYMENT CERTIFICATE</u></strong></p><p style=\"text-align:center\">Number: {{letter_number}}</p><p>The undersigned:</p><table style=\"margin-left:20pt\"><tbody><tr><td style=\"width:120pt\">Name</td><td style=\"width:12pt\">:</td><td><strong>{{signer_name}}</strong></td></tr><tr><td style=\"width:120pt\">Position</td><td style=\"width:12pt\">:</td><td><strong>{{signer_title}}</strong>, {{company}}</td></tr></tbody></table><p>hereby certifies that:</p><p>{{employee_details}}</p><p>is an employee of {{company}}, employed since {{join_date}} up to the date of this letter.</p><p>This certificate is issued for the purpose of {{purpose}}.</p><p>This certificate is issued truthfully, to be used as appropriate.</p><p>{{signature_block}}</p>',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,'2026-10-27 08:09:10','2026-10-27 08:09:10'),(2,'employment_reference','Surat Referensi Kerja','Employment Reference Letter','A reference for the employee\'s work: employee data is filled in automatically, with the period worked and remarks.','required','{\"remarks\": {\"type\": \"textarea\", \"empty\": {\"en\": \"\", \"id\": \"\"}, \"label\": \"Remarks on the employee\'s work\", \"required\": false}, \"end_date\": {\"help\": \"Empty: the employee still works here.\", \"type\": \"date\", \"empty\": {\"en\": \"up to the present\", \"id\": \"sampai dengan saat ini\"}, \"label\": \"Last working day\", \"required\": false}}','<p style=\"text-align:center\"><strong><u>SURAT REFERENSI KERJA</u></strong></p><p style=\"text-align:center\">Nomor: {{letter_number}}</p><p>Kepada pihak yang berkepentingan,</p><p>Yang bertanda tangan di bawah ini, <strong>{{signer_name}}</strong>, {{signer_title}} {{company}}, dengan ini menerangkan bahwa:</p><p>{{employee_details}}</p><p>telah bekerja di {{company}} sejak {{join_date}} {{end_date}}.</p><p>{{remarks}}</p><p>Kami merekomendasikan yang bersangkutan kepada pihak mana pun yang membutuhkan, dan mendoakan kesuksesannya.</p><p>{{signature_block}}</p>','<p style=\"text-align:center\"><strong><u>EMPLOYMENT REFERENCE LETTER</u></strong></p><p style=\"text-align:center\">Number: {{letter_number}}</p><p>To whom it may concern,</p><p>The undersigned, <strong>{{signer_name}}</strong>, {{signer_title}} of {{company}}, hereby states that:</p><p>{{employee_details}}</p><p>has worked at {{company}} from {{join_date}} {{end_date}}.</p><p>{{remarks}}</p><p>We recommend {{employee_name}} to any organisation that may consider them, and wish them every success.</p><p>{{signature_block}}</p>',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,'2026-10-27 08:09:10','2026-10-27 08:09:10'),(3,'assignment_letter','Surat Tugas','Assignment Letter','Assigns the employee to a task at a location for a period, on top of the employee and company data.','required','{\"task\": {\"type\": \"textarea\", \"label\": \"Assignment\", \"required\": true}, \"location\": {\"type\": \"text\", \"label\": \"Location\", \"required\": true}, \"period_to\": {\"type\": \"date\", \"label\": \"Until\", \"required\": true}, \"period_from\": {\"type\": \"date\", \"label\": \"From\", \"required\": true}}','<p style=\"text-align:center\"><strong><u>SURAT TUGAS</u></strong></p><p style=\"text-align:center\">Nomor: {{letter_number}}</p><p>Yang bertanda tangan di bawah ini, <strong>{{signer_name}}</strong>, {{signer_title}} {{company}}, dengan ini menugaskan:</p><p>{{employee_details}}</p><p>untuk melaksanakan tugas sebagai berikut:</p><table style=\"margin-left:20pt\"><tbody><tr><td style=\"width:120pt\">Tugas</td><td style=\"width:12pt\">:</td><td>{{task}}</td></tr><tr><td style=\"width:120pt\">Lokasi</td><td style=\"width:12pt\">:</td><td>{{location}}</td></tr><tr><td style=\"width:120pt\">Periode</td><td style=\"width:12pt\">:</td><td>{{period_from}} s.d. {{period_to}}</td></tr></tbody></table><p>Demikian surat tugas ini dibuat untuk dilaksanakan dengan penuh tanggung jawab dan dilaporkan setelah selesai.</p><p>{{signature_block}}</p>','<p style=\"text-align:center\"><strong><u>ASSIGNMENT LETTER</u></strong></p><p style=\"text-align:center\">Number: {{letter_number}}</p><p>The undersigned, <strong>{{signer_name}}</strong>, {{signer_title}} of {{company}}, hereby assigns:</p><p>{{employee_details}}</p><p>to carry out the following assignment:</p><table style=\"margin-left:20pt\"><tbody><tr><td style=\"width:120pt\">Assignment</td><td style=\"width:12pt\">:</td><td>{{task}}</td></tr><tr><td style=\"width:120pt\">Location</td><td style=\"width:12pt\">:</td><td>{{location}}</td></tr><tr><td style=\"width:120pt\">Period</td><td style=\"width:12pt\">:</td><td>{{period_from}} – {{period_to}}</td></tr></tbody></table><p>Please carry out this assignment responsibly and report on it upon completion.</p><p>{{signature_block}}</p>',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,'2026-10-27 08:09:10','2026-10-27 08:09:10'),(4,'goods_receipt','Tanda Terima','Goods Receipt','Proof that items were handed over: the items received and who they were received from.','optional','{\"items\": {\"type\": \"items\", \"label\": \"Items received\", \"required\": true}, \"received_from\": {\"type\": \"text\", \"label\": \"Received from\", \"required\": true}}','<p style=\"text-align:center\"><strong><u>TANDA TERIMA</u></strong></p><p style=\"text-align:center\">Nomor: {{letter_number}}</p><p>Telah diterima dari <strong>{{received_from}}</strong> barang-barang sebagai berikut:</p><p>{{items}}</p>{{employee_concerned_line}}<p>Demikian tanda terima ini dibuat sebagai bukti bahwa barang-barang di atas telah diterima dengan baik.</p><p>{{signature_block}}</p>','<p style=\"text-align:center\"><strong><u>GOODS RECEIPT</u></strong></p><p style=\"text-align:center\">Number: {{letter_number}}</p><p>The following items have been received from <strong>{{received_from}}</strong>:</p><p>{{items}}</p>{{employee_concerned_line}}<p>This receipt is made as proof that the items above were received in good condition.</p><p>{{signature_block}}</p>','Yang menerima,','Received by,',NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,'2026-10-27 08:09:10','2026-10-27 08:09:10'),(5,'payment_receipt','Kwitansi','Payment Receipt','Proof of a payment received: the amount, the amount in words and what the payment is for.','optional','{\"amount\": {\"type\": \"money\", \"label\": \"Amount (Rp)\", \"required\": true}, \"purpose\": {\"type\": \"textarea\", \"label\": \"For payment of\", \"required\": true}, \"amount_words\": {\"help\": \"Empty: written out automatically in the letter\'s language.\", \"type\": \"text\", \"label\": \"Amount in words\", \"required\": false}, \"received_from\": {\"type\": \"text\", \"label\": \"Received from\", \"required\": true}}','<p style=\"text-align:center\"><strong><u>KWITANSI</u></strong></p><p style=\"text-align:center\">Nomor: {{letter_number}}</p><table style=\"margin-left:0pt\"><tbody><tr><td style=\"width:120pt\">Telah terima dari</td><td style=\"width:12pt\">:</td><td><strong>{{received_from}}</strong></td></tr><tr><td style=\"width:120pt\">Uang sejumlah</td><td style=\"width:12pt\">:</td><td><em>{{amount_words}}</em></td></tr><tr><td style=\"width:120pt\">Untuk pembayaran</td><td style=\"width:12pt\">:</td><td>{{purpose}}</td></tr></tbody></table>{{employee_concerned_line}}<table style=\"border:1pt solid #000000\"><tbody><tr><td style=\"border:1pt solid #000000;padding-left:14pt;font-size:13pt;font-weight:bold\">{{amount}}</td></tr></tbody></table><p>{{signature_block}}</p>','<p style=\"text-align:center\"><strong><u>PAYMENT RECEIPT</u></strong></p><p style=\"text-align:center\">Number: {{letter_number}}</p><table style=\"margin-left:0pt\"><tbody><tr><td style=\"width:120pt\">Received from</td><td style=\"width:12pt\">:</td><td><strong>{{received_from}}</strong></td></tr><tr><td style=\"width:120pt\">The sum of</td><td style=\"width:12pt\">:</td><td><em>{{amount_words}}</em></td></tr><tr><td style=\"width:120pt\">For payment of</td><td style=\"width:12pt\">:</td><td>{{purpose}}</td></tr></tbody></table>{{employee_concerned_line}}<table style=\"border:1pt solid #000000\"><tbody><tr><td style=\"border:1pt solid #000000;padding-left:14pt;font-size:13pt;font-weight:bold\">{{amount}}</td></tr></tbody></table><p>{{signature_block}}</p>','Yang menerima,','Received by,',NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,'2026-10-27 08:09:10','2026-10-27 08:09:10'),(6,'offering_letter','Surat Penawaran Kerja','Offering Letter','Offers a position to a candidate: position, joining date, compensation and benefits. Written here directly — no candidate has to go through the offering process.','none','{\"notes\": {\"type\": \"textarea\", \"empty\": {\"en\": \"-\", \"id\": \"-\"}, \"label\": \"Notes\", \"required\": false}, \"benefits\": {\"type\": \"textarea\", \"empty\": {\"en\": \"-\", \"id\": \"-\"}, \"label\": \"Benefits\", \"required\": false}, \"probation\": {\"help\": \"The sentence to print, e.g. \\\"A probation period of 3 (three) months applies from your joining date.\\\" Empty: nothing is printed.\", \"type\": \"textarea\", \"label\": \"Probation clause\", \"required\": false}, \"salary_type\": {\"type\": \"text\", \"empty\": {\"en\": \"Gross\", \"id\": \"Gross\"}, \"label\": \"Gross or nett\", \"required\": false, \"placeholder\": \"Gross\"}, \"compensation\": {\"help\": \"One line per component (base salary, allowances…) with its monthly amount; the total is added up in the letter.\", \"type\": \"lines\", \"label\": \"Compensation\", \"required\": true}, \"joining_date\": {\"type\": \"date\", \"label\": \"Joining date\", \"required\": true}, \"response_days\": {\"type\": \"text\", \"empty\": {\"en\": \"3\", \"id\": \"3\"}, \"label\": \"Days to respond\", \"required\": false, \"placeholder\": \"3\"}, \"candidate_name\": {\"type\": \"text\", \"label\": \"Candidate name\", \"required\": true}, \"position_title\": {\"type\": \"text\", \"label\": \"Position offered\", \"required\": true}, \"candidate_email\": {\"help\": \"Where Send emails the signed letter.\", \"type\": \"text\", \"label\": \"Candidate email\", \"required\": false}, \"job_description\": {\"help\": \"What the candidate will be doing in this position.\", \"type\": \"textarea\", \"empty\": {\"en\": \"carry out the duties of the position offered.\", \"id\": \"menjalankan tugas sesuai dengan posisi yang ditawarkan.\"}, \"label\": \"Responsibilities\", \"required\": false}}','<p style=\"text-align:center\"><strong><u>OFFERING LETTER</u></strong></p><p style=\"text-align:center\">Nomor: {{letter_number}}</p><p>Kepada Yth,<br>Bapak/Ibu/Saudara/i <strong>{{candidate_name}}</strong><br>Di Tempat</p><p>Dengan Hormat,</p><p>Kami mewakili <strong>{{company}}</strong> menyampaikan bahwa Anda terpilih untuk mengisi posisi <strong>{{position_title}}</strong> di perusahaan kami.</p><p>Anda akan bertugas untuk {{job_description}}</p><p>Kami berharap Anda dapat bergabung pada tanggal <strong>{{joining_date}}</strong>.</p><p><strong>Kompensasi:</strong></p><p>{{compensation}}</p><p>Total kompensasi setiap bulan: <strong>{{compensation_total}}</strong> ({{salary_type}})</p><p>Benefit: {{benefits}}</p><p>{{probation}}</p><p>Catatan: {{notes}}</p><p>Apabila Anda menerima tawaran ini, mohon menandatangani surat ini dan mengembalikannya maksimal {{response_days}} hari sejak tanggal dibuat.</p><table style=\"width:100%\"><tbody><tr><td>{{city}}, {{letter_date}}<br>Hormat kami,</td><td style=\"width:36%\"><br>Menyetujui,</td></tr><tr><td style=\"height:70pt;vertical-align:middle\">{{signature}}</td><td></td></tr><tr><td><strong><u>{{signer_name}}</u></strong><br>{{signer_title}}</td><td><strong>{{candidate_name}}</strong></td></tr></tbody></table>','<p style=\"text-align:center\"><strong><u>OFFERING LETTER</u></strong></p><p style=\"text-align:center\">Number: {{letter_number}}</p><p>To:<br><strong>{{candidate_name}}</strong></p><p>Dear {{candidate_name}},</p><p>On behalf of <strong>{{company}}</strong>, we are pleased to inform you that you have been selected for the position of <strong>{{position_title}}</strong> at our company.</p><p>Your responsibilities will be to {{job_description}}</p><p>We look forward to having you join us on <strong>{{joining_date}}</strong>.</p><p><strong>Compensation:</strong></p><p>{{compensation}}</p><p>Total monthly compensation: <strong>{{compensation_total}}</strong> ({{salary_type}})</p><p>Benefits: {{benefits}}</p><p>{{probation}}</p><p>Notes: {{notes}}</p><p>If you accept this offer, please sign this letter and return it within {{response_days}} days of the date of this letter.</p><table style=\"width:100%\"><tbody><tr><td>{{city}}, {{letter_date}}<br>Sincerely,</td><td style=\"width:36%\"><br>Agreed and accepted by,</td></tr><tr><td style=\"height:70pt;vertical-align:middle\">{{signature}}</td><td></td></tr><tr><td><strong><u>{{signer_name}}</u></strong><br>{{signer_title}}</td><td><strong>{{candidate_name}}</strong></td></tr></tbody></table>',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NULL,NULL,'2026-10-27 08:09:10','2026-10-27 08:09:10');
/*!40000 ALTER TABLE `letter_template_defs` ENABLE KEYS */;
