-- ── Daftarkan migrasi teman di tabel "migrations" (hanya yang belum tercatat) ──
INSERT INTO migrations (migration, batch)
SELECT t.name, (SELECT MAX(x.batch) FROM migrations x)
FROM (
    SELECT '2026_10_26_000001_create_letter_template_defs' AS name
    UNION ALL SELECT '2026_10_26_000002_add_offering_letter_design'
    UNION ALL SELECT '2026_10_27_000001_create_employee_master_settings'
    UNION ALL SELECT '2026_10_27_000002_align_employee_options_with_uat'
) t
WHERE NOT EXISTS (SELECT 1 FROM migrations m WHERE m.migration = t.name);

-- Hasil cek: 4 baris
SELECT migration, batch FROM migrations WHERE migration LIKE '2026_10_26_00000%' OR migration LIKE '2026_10_27_00000%';
